const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const MOD = 998244353;
const n = tok[0], m = tok[1], q = tok[2];
// a * b mod MOD for a, b < 2^30 without leaving the exact range of doubles: split b into 15-bit halves
function mul(a, b) {
  return ((a * (b >>> 15)) % MOD * 32768 + a * (b & 32767)) % MOD;
}
function power(b, e) {
  let r = 1; b %= MOD;
  while (e > 0) { if (e & 1) r = mul(r, b); b = mul(b, b); e = Math.floor(e / 2); }
  return r;
}
const V = 10000;
let size = 1;
while (size < 2 * V + 1) size *= 2;
function ntt(a, invert) {
  const N = a.length;
  for (let i = 1, j = 0; i < N; i++) {
    let bit = N >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) { const t = a[i]; a[i] = a[j]; a[j] = t; }
  }
  for (let length = 2; length <= N; length *= 2) {
    let w = power(3, (MOD - 1) / length);
    if (invert) w = power(w, MOD - 2);
    const half = length / 2;
    const ws = new Array(half).fill(1);
    for (let k = 1; k < half; k++) ws[k] = mul(ws[k - 1], w);
    for (let start = 0; start < N; start += length) {
      for (let k = 0; k < half; k++) {
        const u = a[start + k], v = mul(a[start + k + half], ws[k]);
        a[start + k] = u + v >= MOD ? u + v - MOD : u + v;
        a[start + k + half] = u >= v ? u - v : u - v + MOD;
      }
    }
  }
  if (invert) {
    const invN = power(N, MOD - 2);
    for (let i = 0; i < N; i++) a[i] = mul(a[i], invN);
  }
}
const fa = new Array(size).fill(0), fb = new Array(size).fill(0);
for (let i = 0; i < n; i++) fa[tok[3 + i]]++;
for (let i = 0; i < m; i++) fb[tok[3 + n + i]]++;
ntt(fa, false);
ntt(fb, false);
for (let i = 0; i < size; i++) fa[i] = mul(fa[i], fb[i]);
ntt(fa, true);
const out = [];
for (let i = 0; i < q; i++) out.push(fa[tok[3 + n + m + i]]);
console.log(out.join("\n"));

