import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353L;

    static long power(long b, long e) {
        long r = 1;
        b %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) r = r * b % MOD;
            b = b * b % MOD;
            e >>= 1;
        }
        return r;
    }

    static void ntt(long[] a, boolean invert) {
        int n = a.length;
        for (int i = 1, j = 0; i < n; i++) {
            int bit = n >> 1;
            for (; (j & bit) != 0; bit >>= 1) j ^= bit;
            j ^= bit;
            if (i < j) { long t = a[i]; a[i] = a[j]; a[j] = t; }
        }
        for (int length = 2; length <= n; length <<= 1) {
            long w = power(3, (MOD - 1) / length);
            if (invert) w = power(w, MOD - 2);
            int half = length / 2;
            long[] ws = new long[half];
            ws[0] = 1;
            for (int k = 1; k < half; k++) ws[k] = ws[k - 1] * w % MOD;
            for (int start = 0; start < n; start += length) {
                for (int k = 0; k < half; k++) {
                    long u = a[start + k], v = a[start + k + half] * ws[k] % MOD;
                    a[start + k] = u + v >= MOD ? u + v - MOD : u + v;
                    a[start + k + half] = u >= v ? u - v : u - v + MOD;
                }
            }
        }
        if (invert) {
            long invN = power(n, MOD - 2);
            for (int i = 0; i < n; i++) a[i] = a[i] * invN % MOD;
        }
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken(); int n = (int) in.nval;
        in.nextToken(); int m = (int) in.nval;
        in.nextToken(); int q = (int) in.nval;
        int V = 10000;
        int size = 1;
        while (size < 2 * V + 1) size *= 2;
        long[] fa = new long[size], fb = new long[size];
        for (int i = 0; i < n; i++) { in.nextToken(); fa[(int) in.nval]++; }
        for (int i = 0; i < m; i++) { in.nextToken(); fb[(int) in.nval]++; }
        ntt(fa, false);
        ntt(fb, false);
        for (int i = 0; i < size; i++) fa[i] = fa[i] * fb[i] % MOD;
        ntt(fa, true);
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) { in.nextToken(); out.append(fa[(int) in.nval]).append('\n'); }
        System.out.print(out);
    }
}

