#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MOD = 998244353;

ll power(ll b, ll e) {
    ll r = 1;
    b %= MOD;
    while (e > 0) {
        if (e & 1) r = r * b % MOD;
        b = b * b % MOD;
        e >>= 1;
    }
    return r;
}
void ntt(vector<ll>& a, bool invert) {
    int n = a.size();
    for (int i = 1, j = 0; i < n; i++) {
        int bit = n >> 1;
        for (; j & bit; bit >>= 1) j ^= bit;
        j ^= bit;
        if (i < j) swap(a[i], a[j]);
    }
    for (int length = 2; length <= n; length <<= 1) {
        ll w = power(3, (MOD - 1) / length);
        if (invert) w = power(w, MOD - 2);
        int half = length / 2;
        vector<ll> ws(half, 1);
        for (int k = 1; k < half; k++) ws[k] = ws[k - 1] * w % MOD;
        for (int start = 0; start < n; start += length) {
            for (int k = 0; k < half; k++) {
                ll u = a[start + k], v = a[start + k + half] * ws[k] % MOD;
                a[start + k] = u + v >= MOD ? u + v - MOD : u + v;
                a[start + k + half] = u >= v ? u - v : u - v + MOD;
            }
        }
    }
    if (invert) {
        ll inv_n = power(n, MOD - 2);
        for (ll& x : a) x = x * inv_n % MOD;
    }
}
int main() {
    int n, m, q;
    scanf("%d %d %d", &n, &m, &q);
    int V = 10000;
    int size = 1;
    while (size < 2 * V + 1) size *= 2;
    vector<ll> fa(size, 0), fb(size, 0);
    for (int i = 0; i < n; i++) { int x; scanf("%d", &x); fa[x]++; }
    for (int i = 0; i < m; i++) { int x; scanf("%d", &x); fb[x]++; }
    ntt(fa, false);
    ntt(fb, false);
    for (int i = 0; i < size; i++) fa[i] = fa[i] * fb[i] % MOD;
    ntt(fa, true);
    while (q--) {
        int s;
        scanf("%d", &s);
        printf("%lld\n", fa[s]);
    }
    return 0;
}
